export type Input = {
items: { unit_price: u64; quantity: u64; }[];
discount: u64;
shipping_fee: u64;
free_shipping_minimum: u64;
};

export type Output = {
subtotal: u64;
discount: u64;
shipping: u64;
payable: u64;
};

export default function (in: Input): Output {
const subtotal = in.items
.map((item) => item.unit_price * item.quantity)
.reduce((sum, amount) => sum + amount, 0);
const discount = in.discount > subtotal ? subtotal : in.discount;
const discounted = subtotal - discount;
const shipping = discounted >= in.free_shipping_minimum ? 0 : in.shipping_fee;

return {
subtotal: subtotal,
discount: discount,
shipping: shipping,
payable: discounted + shipping
};
}

